            if (chunk.reason.kind === 'stop' || chunk.reason.kind === 'tool-calls' || chunk.reason.kind === 'max-tokens') announce()
            if (usage) yield usage
            yield chunk
            return
          }
          announce()
          emitted = true
          yield chunk
        }
