      "content": "{\n  \"name\": \"dsh-opencode-go\",\n  \"version\": \"0.2.0\",\n  \"description\": \"OpenCode Go model provider and settings UI for DeepSeek Harness\",\n  \"icon\": \"assets/icon.png\",\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Duskriver/dsh-opencode-go.git\"\n  },\n  \"homepage\": \"https://github.com/Duskriver/dsh-opencode-go#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Duskriver/dsh-opencode-go/issues\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.2.1-rc.5\"\n  },\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"assets/icon.png\",\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"docs\",\n    \"examples\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-ui-model-selection\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"compile\": \"node scripts/build.mjs\",\n    \"check:dist\": \"node scripts/build.mjs --check\",\n    \"typecheck\": \"tsc -p tsconfig.host.json --noEmit && tsc -p tsconfig.client.json --noEmit\",\n    \"test\": \"vitest run\",\n    \"test:ci\": \"npm run check:dist && npm test\",\n    \"verify:installed\": \"node --expose-internals scripts/installed-smoke.mjs\",\n    \"verify:headless\": \"node scripts/headless-smoke.mjs\",\n    \"verify\"