tomic-write\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-attachment\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-model-selection\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-credentials\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-credentials-local\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-deque\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-fs\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-home-paths\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-launch-environment\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-native-command\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-ptc-runtime\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-sandbox\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-session-projection\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-timeout\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-typert-registry\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-util-code-language\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-util-crypto\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-util-values\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-util-workspace-path\": \"0.2.1-rc.5\",\n    \"@google/genai\": \"2.21.0\",\n    \"@shikijs/langs\": \"^4.3.1\",\n    \"@testing-library/dom\": \"^10.4.2\",\n    \"@testing-library/react\": \"^16.3.2\",\n    \"@types/mdast\": \"^4.0.4\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.0\",\n    \"@types/semver\": \"7.8.0\",\n    \"anser\": \"^2.3.5\",\n    \"clsx\": \"^2.0.0\",\n    \"diff\": \"^9.0.0\",\n    \"esbuild\": \"^0.25.0\",\n    \"immer\": \"^10.1.1\",\n    \"jsdom\": \"29.1.1\",\n    \"katex\": \"^0.16.47\",\n    \"lightningcss\": \"^1.32.0\",\n    \"mdast-util-from-markdown\": \"^2.0.3\",\n    \"mdast-util-gfm\": \"^3.1.0\",\n    \"mdast-util-math\": \"^3.0.0\",\n    \"micromark-core-commonmark\": \"^2.0.3\",\n    \"micromark-extension-gfm\": \"^3.0.0\",\n    \"micromark-extension-math\": \"^3.1.0\",\n    \"micromark-factory-space\": \"^2.0.1\",\n    \"micromark-util-character\": \"^2.1.1\",\n    \"micromark-util-classify-character\": \"^2.0.1\",\n    \"micromark-util-sanitize-uri\": \"^2.0.1\",\n    \"micromark-util-symbol\": \"^2.0.1\",\n    \"micromark-util-types\": \"^2.0.2\",\n    \"opencode-go-pi-ai\": \"npm:@earendil-works/pi-ai@1.5.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"rollup\": \"^4.64.2\",\n    \"rollup-plugin-dts\": \"^6.5.1\",\n    \"semver\": \"7.8.5\",\n    \"shiki\": \"^4.3.1\",\n    \"simple-icons\": \"16.31.0\",\n    \"typescript\": \"6.0.3\",\n    \"vitest\": \"^4.1.8\",\n    \"zustand\": \"~4.4.7\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-api-remotes\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-api-gateway\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-api-settings-controller\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-store\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-renderer\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-model-selection\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-conversation\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-typert-registry\": {\n      \"optional\": true\n    }\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"dsh\",\n    \"opencode\",\n    \"opencode-go\",\n    \"llm\",\n    \"cordis\"\n  ]\n}\n"
